{
  "packet_id": "H6-T03-2",
  "claim_id": "C011",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C011.component",
    "value": "A delegation establishes authority only within the delegation's terms.",
    "scope": "Authority attributable to a particular delegation; unrestricted authority is not inferred.",
    "provenance": {
      "refs": [
        {
          "source_id": "P008",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P008 explicitly limits the authority established by a delegation to its terms."
    }
  },
  "signal_basis": {
    "component_id": "C011.signal_basis",
    "value": "Examine the delegation's terms and independently originating records agreeing on the approver's authority at the relevant time and the approval's scope; unclear delegation terms indicate uncertainty.",
    "scope": "Authority for the particular order and relevant time; delegation alone does not establish approval of that order.",
    "provenance": {
      "refs": [
        {
          "source_id": "P008",
          "role": "SUPPORT"
        },
        {
          "source_id": "P015",
          "role": "SUPPORT"
        },
        {
          "source_id": "P017",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the delegation's limits, the corroborating authority and scope checks, and the uncertainty associated with unclear terms."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C011.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The bounded claim is supported without an additional unresolved empirical relation."
    }
  },
  "rationale": "A delegation confers authority within its specified terms. Given the stipulated checks and signal, attributing authority within those bounds is licensed; the claim does not infer unrestricted authority or approval of a particular order.",
  "uncertainty": "Unclear delegation terms leave the extent of authority unresolved, as P017 specifies, without undermining the stated restriction.",
  "anomalies": []
}
